function formatDateToYYYYMM(date) {
    const year = date.getFullYear();
    const month = ("0" + (date.getMonth() + 1)).slice(-2); // getMonth()返回0-11，所以需要+1，并补0以确保始终为两位数
    return year+""+month;
}

